class TrainReader {
    private var generation: Long? = null

    fun read(client: fr.nimby.sdk.NimbyClient, id: Long) {
        val sample = client.readTrain(id)
        if (sample == null) {
            println("Observation indisponible")
            return
        }
        if (generation != sample.sessionGeneration) {
            // Effacer ici les calculs qui dépendaient de la partie précédente.
            generation = sample.sessionGeneration
        }
        if (sample.speedDefaulted) println("Zéro de présentation, pas une mesure")
        else println(sample.speedMps?.times(3.6))
    }

    fun disconnected() { generation = null }
}

